package main

import (
	"bytes"
	"encoding/json"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"reflect"
	"sort"
	"strconv"
	"strings"
	"testing"
)

// wireContractPath is the payload generated by the daemon-side core test. The
// TUI is a separate module and imports no Beacon package, so it decodes the
// shared file with its own wire structs.
const wireContractPath = "../../docs/wire/loopback.json"

// coreVocabularyPath is the core source that declares the control verbs. The
// TUI imports no Beacon package, so the contract test resolves core's names
// from source instead of importing them.
const coreVocabularyPath = "../../pkg/core/control.go"

type wireContractPayload struct {
	Runs    []Run         `json:"runs"`
	Event   Event         `json:"event"`
	Control ControlResult `json:"control"`
}

// wirePingPayload and wirePRChangedPayload are the data shapes of the two
// non-harness events the events route emits. The harness event shape is pinned
// by the Event field of wireContractPayload.
type wirePingPayload struct {
	Time string `json:"time"`
}

type wirePRChangedPayload struct {
	PR int `json:"pr"`
}

// decodeWireStrict rejects unknown keys. json.Unmarshal silently ignores a
// field the target does not name, so a daemon-side field addition would pass
// this contract unnoticed. The decoder is shared by every fixture below.
func decodeWireStrict(data []byte, dst any) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	return dec.Decode(dst)
}

// TestWireContractDecode proves the monitor reads every field the daemon
// emits. If a core wire tag is renamed, the core test regenerates the file and
// this test fails on the fields it can no longer decode. If a field is added,
// the strict decoder rejects it until the monitor learns the field too.
func TestWireContractDecode(t *testing.T) {
	data, err := os.ReadFile(wireContractPath)
	if err != nil {
		t.Fatalf("read %s: %v", wireContractPath, err)
	}
	var got wireContractPayload
	if err := decodeWireStrict(data, &got); err != nil {
		t.Fatalf("decode wire contract: %v", err)
	}

	want := wireContractPayload{
		Runs: []Run{{
			ID:        "run-contract-1",
			TaskID:    "T-CONTRACT",
			State:     "waiting_ci",
			PR:        42,
			HeadSHA:   "deadbeef",
			Branch:    "beacon/T-CONTRACT",
			Reason:    "checking CI",
			UpdatedAt: "2026-11-25T10:00:00Z",
		}},
		Event: Event{
			ID:    17,
			Type:  "idle",
			RunID: "run-contract-1",
			At:    "2026-11-25T10:00:00Z",
		},
		Control: ControlResult{
			OK:      true,
			RunID:   "run-contract-1",
			Action:  "approve",
			Applied: true,
		},
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("wire contract decoded as %+v, want %+v", got, want)
	}
}

// TestWireEventPayloadFixtures pins the data lines of the ping and pr_changed
// frames. Each fixture uses the strict decoder, so a new key in a daemon event
// payload fails the test instead of being ignored.
func TestWireEventPayloadFixtures(t *testing.T) {
	t.Run("ping", func(t *testing.T) {
		var got wirePingPayload
		if err := decodeWireStrict([]byte(`{"time":"2026-11-25T10:00:00Z"}`), &got); err != nil {
			t.Fatalf("decode ping fixture: %v", err)
		}
		want := wirePingPayload{Time: "2026-11-25T10:00:00Z"}
		if got != want {
			t.Fatalf("ping fixture decoded as %+v, want %+v", got, want)
		}
	})

	t.Run("pr_changed", func(t *testing.T) {
		var got wirePRChangedPayload
		if err := decodeWireStrict([]byte(`{"pr":42}`), &got); err != nil {
			t.Fatalf("decode pr_changed fixture: %v", err)
		}
		want := wirePRChangedPayload{PR: 42}
		if got != want {
			t.Fatalf("pr_changed fixture decoded as %+v, want %+v", got, want)
		}
	})
}

// coreControlVerbs resolves core.ControlActions through the Control* constants
// declared beside it. The returned order is the wire order core publishes.
func coreControlVerbs(t *testing.T) []string {
	t.Helper()
	f, err := parser.ParseFile(token.NewFileSet(), coreVocabularyPath, nil, 0)
	if err != nil {
		t.Fatalf("parser.ParseFile(%q): %v", coreVocabularyPath, err)
	}
	constants := map[string]string{}
	var verbs []string
	for _, decl := range f.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok {
			continue
		}
		for _, spec := range gen.Specs {
			values, ok := spec.(*ast.ValueSpec)
			if !ok {
				continue
			}
			switch gen.Tok {
			case token.CONST:
				for i, name := range values.Names {
					if i >= len(values.Values) {
						continue
					}
					lit, ok := values.Values[i].(*ast.BasicLit)
					if !ok || lit.Kind != token.STRING {
						continue
					}
					value, err := strconv.Unquote(lit.Value)
					if err != nil {
						t.Fatalf("%s: unquote %s: %v", coreVocabularyPath, lit.Value, err)
					}
					constants[name.Name] = value
				}
			case token.VAR:
				if len(values.Names) != 1 || values.Names[0].Name != "ControlActions" {
					continue
				}
				if len(values.Values) != 1 {
					t.Fatalf("%s: ControlActions has %d values", coreVocabularyPath, len(values.Values))
				}
				array, ok := values.Values[0].(*ast.CompositeLit)
				if !ok {
					t.Fatalf("%s: ControlActions is not a literal array", coreVocabularyPath)
				}
				for _, element := range array.Elts {
					id, ok := element.(*ast.Ident)
					if !ok {
						t.Fatalf("%s: ControlActions has a non-constant element", coreVocabularyPath)
					}
					verb, ok := constants[id.Name]
					if !ok {
						t.Fatalf("%s: action %s has no constant value", coreVocabularyPath, id.Name)
					}
					verbs = append(verbs, verb)
				}
			}
		}
	}
	if len(verbs) == 0 {
		t.Fatalf("%s: core vocabulary is empty", coreVocabularyPath)
	}
	return verbs
}

// TestControlVocabularyMatchesCore proves the TUI sends exactly the verbs core
// accepts. Adding a core action without a TUI action changes the expected list
// and fails this test.
func TestControlVocabularyMatchesCore(t *testing.T) {
	want := coreControlVerbs(t)
	got := make([]string, 0, len(actions))
	for _, action := range actions {
		got = append(got, string(action))
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("TUI actions = %v, core.ControlActions = %v", got, want)
	}
}

// wireFieldTable is the one table of monitor wire fields. It sits beside the
// golden payload: the generator below derives the fields from the committed
// file and the parity tests fail when a field is added on either side without
// a matching row here. A trailing ? marks a field the daemon omits when empty;
// it can be absent from the golden payload but must still be named here.
var wireFieldTable = map[string][]string{
	"runs":       {"id", "task_id", "state", "pr", "head_sha", "branch", "reason", "updated_at"},
	"event":      {"id", "type", "run_id", "at"},
	"control":    {"ok", "action", "run_id", "applied", "reason?"},
	"ping":       {"time"},
	"pr_changed": {"pr"},
}

// goldenFields generates the field table carried by the committed payload. It
// decodes into raw objects so a new key is visible even before the monitor
// knows how to read it.
func goldenFields(t *testing.T) map[string][]string {
	t.Helper()
	data, err := os.ReadFile(wireContractPath)
	if err != nil {
		t.Fatalf("read %s: %v", wireContractPath, err)
	}
	var root map[string]json.RawMessage
	if err := json.Unmarshal(data, &root); err != nil {
		t.Fatalf("decode %s: %v", wireContractPath, err)
	}
	out := make(map[string][]string, len(root))
	for shape, raw := range root {
		if shape == "runs" {
			var items []map[string]json.RawMessage
			if err := json.Unmarshal(raw, &items); err != nil {
				t.Fatalf("decode runs: %v", err)
			}
			if len(items) == 0 {
				t.Fatal("runs is empty, cannot derive its fields")
			}
			out[shape] = sortedObjectKeys(items[0])
			for i, item := range items[1:] {
				if !reflect.DeepEqual(sortedObjectKeys(item), out[shape]) {
					t.Fatalf("runs[%d] fields differ from runs[0]", i+1)
				}
			}
			continue
		}
		var obj map[string]json.RawMessage
		if err := json.Unmarshal(raw, &obj); err != nil {
			t.Fatalf("decode %s: %v", shape, err)
		}
		out[shape] = sortedObjectKeys(obj)
	}
	return out
}

func sortedObjectKeys(obj map[string]json.RawMessage) []string {
	keys := make([]string, 0, len(obj))
	for key := range obj {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	return keys
}

// sortedTable strips the optional marker and returns the field names in a
// stable order. It is the expected set for the monitor wire structs.
func sortedTable(table map[string][]string) map[string][]string {
	out := make(map[string][]string, len(table))
	for shape, fields := range table {
		names := make([]string, 0, len(fields))
		for _, field := range fields {
			names = append(names, strings.TrimSuffix(field, "?"))
		}
		sort.Strings(names)
		out[shape] = names
	}
	return out
}

// requiredTable keeps only the fields that must appear in every golden
// payload. Optional fields may be absent when the daemon leaves them empty.
func requiredTable(table map[string][]string) map[string][]string {
	out := make(map[string][]string, len(table))
	for shape, fields := range table {
		names := []string{}
		for _, field := range fields {
			if !strings.HasSuffix(field, "?") {
				names = append(names, field)
			}
		}
		sort.Strings(names)
		out[shape] = names
	}
	return out
}

func containsField(fields []string, want string) bool {
	for _, field := range fields {
		if field == want {
			return true
		}
	}
	return false
}

// TestWireFieldTableMatchesGolden fails when the daemon adds a wire field
// without a row in wireFieldTable, or drops a required one. The core test
// regenerates the golden file from the real wire types; this test reads the
// generated bytes back.
func TestWireFieldTableMatchesGolden(t *testing.T) {
	got := goldenFields(t)
	allowed := sortedTable(wireFieldTable)
	required := requiredTable(wireFieldTable)
	goldenShapes := []string{"runs", "event", "control"}
	if len(got) != len(goldenShapes) {
		t.Fatalf("golden shapes = %v, want %v", keysOf(got), goldenShapes)
	}
	for _, shape := range goldenShapes {
		for _, field := range got[shape] {
			if !containsField(allowed[shape], field) {
				t.Errorf("golden %s has field %q missing from the field table", shape, field)
			}
		}
		for _, field := range required[shape] {
			if !containsField(got[shape], field) {
				t.Errorf("golden %s is missing required field %q", shape, field)
			}
		}
	}
}

func keysOf(table map[string][]string) []string {
	keys := make([]string, 0, len(table))
	for key := range table {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	return keys
}

// structJSONFields returns the json field names of a monitor wire struct. The
// field table covers the monitor structs too, so a field added here also needs
// one row.
func structJSONFields(typ reflect.Type) []string {
	out := make([]string, 0, typ.NumField())
	for i := 0; i < typ.NumField(); i++ {
		tag := typ.Field(i).Tag.Get("json")
		if tag == "" || tag == "-" {
			continue
		}
		name := strings.Split(tag, ",")[0]
		if name != "" {
			out = append(out, name)
		}
	}
	sort.Strings(out)
	return out
}

// TestWireFieldTableMatchesMonitorStructs fails when a monitor wire struct
// gains a field without a row in wireFieldTable.
func TestWireFieldTableMatchesMonitorStructs(t *testing.T) {
	got := map[string][]string{
		"runs":       structJSONFields(reflect.TypeOf(Run{})),
		"event":      structJSONFields(reflect.TypeOf(Event{})),
		"control":    structJSONFields(reflect.TypeOf(ControlResult{})),
		"ping":       structJSONFields(reflect.TypeOf(wirePingPayload{})),
		"pr_changed": structJSONFields(reflect.TypeOf(wirePRChangedPayload{})),
	}
	want := sortedTable(wireFieldTable)
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("monitor struct fields = %v, field table = %v", got, want)
	}
}
